<?php
namespace Tests\Unit;use PHPUnit\Framework\TestCase;
class RankHistoryCorrectionPhaseTTest extends TestCase
{private function s(string$p):string{return file_get_contents(ROOTPATH.$p);}public function testCorrectionTypesReasonAndLineage():void{$m=$this->s('app/Database/Migrations/2026-09-15-000015_AddRankCorrectionAndCancellation.php');foreach(['personnel_rank_corrections','source_approved_rank_record_id','data','substantive']as$x)self::assertStringContainsString($x,$m);$s=$this->s('app/Services/RankHistoryCorrectionService.php');self::assertStringContainsString('CORRECTION_REASON_REQUIRED',$s);self::assertStringContainsString("'record_kind'=>'correction'",$s);}public function testOriginalFactsAreNotOverwritten():void{$s=$this->s('app/Services/RankHistoryCorrectionService.php');$update=substr($s,strpos($s,"where('id',\$id)->update"),180);self::assertStringContainsString("['status'=>'corrected']",$update);self::assertStringNotContainsString('approved_rank_code',$update);self::assertStringNotContainsString('effectivity_date',$update);}public function testDocumentReuseAndSubstantiveReplacementRules():void{$s=$this->s('app/Services/RankHistoryCorrectionService.php');foreach(['original_document_still_supports','NEW_DOCUMENT_REQUIRED_FOR_SUBSTANTIVE_CORRECTION','CORRECTION_SUPPORTING_DOCUMENT_REQUIRED','correction_document_reused','correction_document_supplied']as$x)self::assertStringContainsString($x,$s);}public function testPendingReplacementAndOverlapProtection():void{$s=$this->s('app/Services/RankHistoryCorrectionService.php');self::assertStringContainsString("'replacement_pending_created'",$s);self::assertStringContainsString('CORRECTED_RANK_PERIOD_OVERLAP',$s);$m=$this->s('app/Database/Migrations/2026-09-15-000014_AddApprovedRankActivationRecovery.php');self::assertStringContainsString('uq_approved_rank_pending_personnel',$m);}public function testHistoricalTimelineIsNotSilentlyRebased():void{$s=$this->s('app/Services/RankHistoryCorrectionService.php');self::assertStringContainsString('HISTORICAL_TIMELINE_REBASE_REQUIRES_EXPLICIT_POLICY',$s);self::assertStringNotContainsString('delete()',$s);}public function testFutureCancellationPreservesHistoryAndPresentRank():void{$s=$this->s('app/Services/RankHistoryCorrectionService.php');self::assertStringContainsString('ONLY_FUTURE_PENDING_RANK_CAN_BE_CANCELLED',$s);self::assertStringContainsString("['status'=>'cancelled']",$s);$cancel=substr($s,strpos($s,'public function cancel'),strpos($s,'public function history')-strpos($s,'public function cancel'));self::assertStringNotContainsString('current_rank_title',$cancel);self::assertStringNotContainsString('delete()',$cancel);}public function testCancellationReleasesPendingGuardForPhaseRReplacement():void{$m=$this->s('app/Database/Migrations/2026-09-15-000015_AddRankCorrectionAndCancellation.php');self::assertStringContainsString("status<>'cancelled'",$m);$r=$this->s('app/Services/OfflineApprovedRankService.php');self::assertStringContainsString("where('status !=','cancelled')",$r);}public function testAuthorizationAndVisibility():void{$s=$this->s('app/Services/RankHistoryCorrectionService.php');self::assertStringContainsString('RANK_HISTORY_HR_ONLY',$s);$review=$this->part($s,'private function reviewerProjection','private function correction');self::assertStringNotContainsString('reason',$review);self::assertStringNotContainsString('signed_document',$review);self::assertStringContainsString("\$r['correction']=\$c",$s);}public function testSignedDocumentAccessDoesNotExpand():void{$s=$this->s('app/Services/OfflineApprovedRankService.php');self::assertStringContainsString('SIGNED_APPROVED_DOCUMENT_ACCESS_DENIED',$s);}private function part(string$s,string$a,string$b):string{$i=strpos($s,$a);$j=strpos($s,$b,$i);return substr($s,$i,$j-$i);}}
